// Vibes Brain — Error & Alert: one short, key-free alert per failed execution
const e = $json || {};
const ex = e.execution || {};
const wf = e.workflow || {};
const err = ex.error || {};
const NL = String.fromCharCode(10);
const scrub = s => String(s || '').replace(/[A-Za-z0-9_-]{32,}/g, '[key]').slice(0, 600);
const when = new Date().toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh' });
const text = ['⚠️ خطأ في عقل n8n (' + String(wf.name || '') + ')', 'الوقت: ' + when, 'التنفيذ: ' + String(ex.id || '') + (ex.url ? ' — ' + ex.url : ''), 'آخر عقدة: ' + String(ex.lastNodeExecuted || ''), 'الخطأ: ' + scrub(err.message), 'الوضع: ' + String(ex.mode || '')].join(NL);
return [{ json: { source: 'n8n', workflow: String(wf.name || ''), workflow_id: String(wf.id || ''), execution_id: String(ex.id || ''), node: String(ex.lastNodeExecuted || ''), message: scrub(err.message), text } }];
